  updateTime?: string;
};

type BusinessProfileResponse = {
  reviews?: BusinessProfileReview[];
  averageRating?: number;
  totalReviewCount?: number;
  nextPageToken?: string;
};

type PlacesReview = {
  name?: string;
  rating?: number;

  text?: {
    text?: string;
  };

