/*
  The close button sits slightly outside the modal.
  Modal shell must not clip it.
*/
.modalShell {
  overflow: visible;
}

/*
  Scroll clipping stays inside the content container,
  so the modal content remains clean and rounded.
*/
.scrollArea {
