                                        : "Select the kitchen services you need"}
                                    </p>
                                  </div>
                                ) : (
                                  <div>
                                    <div className={styles.extraAreaOptions}>
                                      {extraAreaOptions.map((option) => {
                                        const selected =
                                          extraAreaSelections.some(
                                            (item) =>
                                              item.id === option.id,
                                          );

                                        return (
                                          <button
                                            key={option.id}
                                            type="button"
                                            className={`${styles.extraAreaOption} ${
                                              selected
                                                ? styles.extraAreaOptionSelected
                                                : ""
                                            }`}
                                            aria-pressed={selected}
                                            onClick={() => {
                                              setExtraAreaSelections(
                                                (current) => {
                                                  const alreadySelected =
                                                    current.some(
                                                      (item) =>
                                                        item.id ===
                                                        option.id,
                                                    );

                                                  if (alreadySelected) {
                                                    return current.filter(
                                                      (item) =>
                                                        item.id !==
                                                        option.id,
                                                    );
                                                  }

                                                  return [
                                                    ...current,
                                                    {
                                                      id: option.id,
                                                      label: option.label,
                                                      price: option.price,
                                                    },
                                                  ];
                                                },
                                              );
                                            }}
                                          >
                                            <span>
                                              {option.label}
                                            </span>

                                            <strong>
                                              + {option.priceLabel}
                                            </strong>
                                          </button>
                                        );
                                      })}
                                    </div>

                                    <p className={styles.extraAreaHint}>
                                      Select any extra spaces you want included.
