                    handleAddSurvey
                  }
                >
                  Add site survey
                </button>
              </footer>
            </div>
          </div>,
          document.body,
        )
      : null;

  return (
    <>
      <button
        type="button"
        className={buttonClassName}
        onClick={() =>
          setIsOpen(true)
        }
      >
        {buttonLabel}
      </button>

      {modal}
    </>
  );
}

