export default function DeepCleaningSelectorModal({
  open,
  onClose,
}: DeepCleaningSelectorModalProps) {
const dialogRef = useRef<HTMLDivElement>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
useEffect(() => {
    if (!open) {
      return;
    }

    const previousOverflow = document.body.style.overflow;
    const previousPaddingRight = document.body.style.paddingRight;

    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;

    const previousActiveElement =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;

    document.body.style.overflow = "hidden";

    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    const focusTimer = window.setTimeout(() => {
      closeButtonRef.current?.focus();
    }, 0);

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
        return;
      }

      if (event.key !== "Tab") {
        return;
      }

      const dialog = dialogRef.current;

      if (!dialog) {
        return;
      }

      const focusableElements = Array.from(
        dialog.querySelectorAll<HTMLElement>(
          'button:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])',
        ),
      );

      if (focusableElements.length === 0) {
        return;
      }

      const firstElement = focusableElements[0];
      const lastElement =
        focusableElements[focusableElements.length - 1];

      if (
        event.shiftKey &&
        document.activeElement === firstElement
      ) {
        event.preventDefault();
        lastElement.focus();
      } else if (
        !event.shiftKey &&
        document.activeElement === lastElement
      ) {
        event.preventDefault();
        firstElement.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      window.clearTimeout(focusTimer);

      document.body.style.overflow = previousOverflow;
      document.body.style.paddingRight =
        previousPaddingRight;

      document.removeEventListener(
        "keydown",
        handleKeyDown,
      );

      previousActiveElement?.focus();
    };
  }, [open, onClose]);

  if (!open || typeof document === "undefined") {
    return null;
  }

  return createPortal(
    <div
      className={styles.overlay}
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) {
          onClose();
        }
      }}
    >
      <div
        ref={dialogRef}
        className={styles.dialogPositioner}
      >
        <button
          ref={closeButtonRef}
          type="button"
          className={styles.closeButton}
          aria-label="Close Deep Cleaning services"
          onClick={onClose}
        >
          <svg
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path d="M6 6L18 18M18 6L6 18" />
          </svg>
        </button>

        <section
          className={styles.modal}
          role="dialog"
          aria-modal="true"
          aria-labelledby="deep-cleaning-selector-title"
        >
          <h2
            id="deep-cleaning-selector-title"
            className={styles.title}
          >
            Deep Cleaning
          </h2>

          <h3 className={styles.groupTitle}>
            Cleaning
          </h3>

          <div
            className={styles.grid}
            aria-label="Deep Cleaning categories"
          >
            {deepCleaningServices.map((service) => (
              <Link
                key={service.id}
                href={`/services/deep-cleaning?category=${service.id}`}
                className={styles.serviceCard}
                onClick={onClose}
              >
                <span
                  className={styles.imageArea}
                  aria-hidden="true"
                >
                  {service.icon ? (
                    <Image loading="eager"
                      src={serviceDisplaySource(service.icon)}
                      alt=""
                      width={80}
                      height={80}
                      unoptimized
                      className={styles.serviceIcon}
                    />
                  ) : null}
                </span>

                <span className={styles.serviceName}>
                  {service.name}
                </span>
              </Link>
            ))}
          </div>
        </section>
      </div>
    </div>,
    document.body,
  );
}








