type FullHomeByRoomCleaningSectionProps = {
  rating?: number | null;
  bookingsLabel?: string | null;
};

function scrollToServiceTarget(
  targetId: string,
  targetLabel: string,
) {
  const directTarget = document.getElementById(targetId);

  const headingTarget =
    directTarget ??
    Array.from(
      document.querySelectorAll<HTMLElement>(
        "h1, h2, h3, [data-service-scroll-target]",
      ),
    ).find((element) => {
      const text =
        element.textContent
          ?.replace(/\s+/g, " ")
          .trim()
          .toLowerCase() ?? "";

      return text === targetLabel.toLowerCase();
    });

  if (!headingTarget) {
    return;
  }

  const top =
    headingTarget.getBoundingClientRect().top +
    window.scrollY -
    150;

  window.scrollTo({
    top: Math.max(0, top),
    behavior: "smooth",
  });
}
