  flex: 1 1 auto;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 28px 32px 34px;
  overscroll-behavior: contain;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
}

.modalBody::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ======================================================
   POPUP PRICING
   ====================================================== */

.modalSection {
  width: 100%;
}

.modalSection + .modalSection,
.ratingSection {
  margin-top: 30px;
  padding-top: 28px;
  border-top: 1px solid #e9eaec;
}

.modalSection h3 {
  margin: 0 0 19px;
  color: #5c6678;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
}

.pricingGrid {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.priceCard {
  display: flex;
  box-sizing: border-box;
  min-height: 168px;
  padding: 16px 13px;
  border: 1px solid #dfe2e7;
  border-radius: 10px;
  background: #ffffff;
  flex-direction: column;
  align-items: flex-start;
}

.optionLabel {
  color: #303746;
  font-size: 15px;
  font-weight: 400;
  line-height: 1.42;
}

.priceCard strong {
  margin-top: 20px;
  color: #525d6f;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.25;
}

.priceCard button {
  display: inline-flex;
  min-width: 85px;
  min-height: 42px;
  margin-top: auto;
  padding: 0 18px;
  align-items: center;
  justify-content: center;
  border: 1.5px solid #ef1b23;
  border-radius: 9px;
  background: #ffffff;
  color: #ef1b23;
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
}

.priceCard button:hover,
.priceCard button:focus-visible {
  background: #ef1b23;
  color: #ffffff;
}

/* ======================================================
   PROCESS / INCLUDED
   ====================================================== */

.processList {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
  flex-direction: column;
  gap: 18px;
}

.processList li {
  display: grid;
  grid-template-columns: 29px minmax(0, 1fr);
  gap: 3px;
}

.processNumber {
  color: #7b8495;
  font-size: 15px;
  line-height: 1.45;
}

.processList strong {
  color: #606a7c;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.4;
}

.processList p {
  margin: 4px 0 0;
  color: #7b8598;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.55;
}

.simpleList {
  display: flex;
  margin: 0;
  padding: 0 0 0 21px;
  color: #697387;
  flex-direction: column;
  gap: 14px;
}

.simpleList li {
  padding-left: 5px;
  font-size: 15px;
  line-height: 1.45;
}

/* ======================================================
   RATING
   ====================================================== */

.ratingSection {
  padding-bottom: 8px;
}

.ratingSummary {
  display: flex;
  align-items: center;
  gap: 10px;
}

.goldStar {
  color: #f6b900;
  font-size: 28px;
  line-height: 1;
}

.ratingSummary strong {
  color: #586171;
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
}

.ratingReviewCount {
  margin: 10px 0 24px;
  color: #7e8797;
  font-size: 14px;
  line-height: 1.4;
}

.ratingBars {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 15px;
}

.ratingBarRow {
  display: grid;
  width: 100%;
  grid-template-columns: 34px minmax(0, 1fr) 43px;
  gap: 10px;
  align-items: center;
}

.ratingLabel {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: #596273;
  font-size: 14px;
  line-height: 1;
}

.ratingLabel span {
  color: #f6b900;
}

.ratingTrack {
  display: block;
  width: 100%;
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: #d4d4d4;
}

.ratingFill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #ef1b23;
}

.ratingPercent {
  color: #7c8595;
  font-size: 13px;
  text-align: right;
}

