function formatCurrency(
  value: number,
): string {
  return `₹${value.toLocaleString(
    "en-IN",
  )}`;
}

function getStartingPrice(
  service: CleaningService,
): number {
  return Math.min(
    ...service.options.map(
      (option) => option.price,
    ),
  );
}

function scrollToService(
  targetId: string,
) {
  const target =
    document.getElementById(
      targetId,
    );

  if (!target) {
    return;
  }

  const top =
    target.getBoundingClientRect().top +
    window.scrollY -
    155;

  window.scrollTo({
    top: Math.max(
      0,
      top,
    ),
    behavior: "smooth",
  });
}

