  width: 72px;
  height: 72px;
  flex: 0 0 72px;
  border: 0;
  border-radius: 0;
  background: #fff1f3;
}

.selectorLabel {
  width: 88px;
  color: #111111;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.15;
  text-align: center;
}

.selectorItem:hover .selectorLabel,
.selectorItem:focus-visible .selectorLabel {
  color: #ef1b23;
}

.selectorItem:focus-visible {
  outline: 2px solid #ef1b23;
  outline-offset: 5px;
}

.selectorDivider {
  width: 100%;
  height: 1px;
  margin: 26px 0 28px;
  background: transparent;
}

/* ======================================================
   MAIN + RIGHT SIDEBAR
   ====================================================== */

.contentLayout {
  display: grid;
  width: 100%;
  grid-template-columns:
    minmax(0, 696px)
    minmax(300px, 372px);
  gap: 32px;
  align-items: start;
}

.mainColumn {
  min-width: 0;
}

.sidebarColumn {
  position: sticky;
  top: 170px;
  min-width: 0;
}

.serviceGroup {
  width: 100%;
  scroll-margin-top: 155px;
  padding: 0 0 34px;
}

.serviceGroup + .serviceGroup {
  padding-top: 34px;
  border-top: 1px solid #f0dfe2;
}

.serviceGroup > h2 {
  margin: 0 0 30px;
  color: #111111;
  font-size: 38px;
  font-weight: 700;
  line-height: 1.16;
  letter-spacing: -0.035em;
}

.serviceList {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 28px;
}

/* ======================================================
   SERVICE BLOCK - SAME VISUAL STRUCTURE AS FULL HOME
   ====================================================== */

.serviceCard {
  width: 100%;
  margin: 0;
  padding: 0 0 18px;
  border: 0;
  border-bottom: 1px solid rgba(40, 40, 40, 0.11);
  border-radius: 0;
  background: transparent;
}

/*
 * Actual service images will be added later.
 * This keeps the same banner footprint as Full Home.
 */
.bannerPlaceholder {
  box-sizing: border-box;
  width: 100%;
  aspect-ratio: 2.36 / 1;
  overflow: hidden;
  border: 1px solid #f3ccd2;
  border-radius: 12px;
  background: #fff1f3;
}

.serviceDetails {
  width: 100%;
  padding: 17px 0 0;
}

.serviceMainRow {
  display: flex;
  width: 100%;
  gap: 18px;
  align-items: flex-start;
  justify-content: space-between;
}

.serviceInformation {
  min-width: 0;
  flex: 1 1 auto;
}

.serviceTitle {
  margin: 0;
  color: #171717;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.34;
}

.ratingRow {
  display: flex;
  margin-top: 8px;
  flex-wrap: nowrap;
  align-items: center;
  gap: 5px;
  color: #555555;
  font-size: 13px;
  line-height: 1.3;
  white-space: nowrap;
}

.ratingIcon {
  display: inline-flex;
  width: 20px;
  height: 20px;
  min-width: 20px;
  flex: 0 0 20px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #ef1b23;
  color: #ffffff;
  font-size: 10px;
  line-height: 1;
}

.reviewText {
  flex: 0 0 auto;
  white-space: nowrap;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

.detailsButton {
  flex: 0 0 auto;
  margin: 0 0 0 4px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #ef1b23;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.3;
  white-space: nowrap;
}

.priceRow {
  display: flex;
  margin-top: 9px;
  align-items: center;
  gap: 7px;
  color: #171717;
  font-size: 13px;
  line-height: 1.3;
}

.priceRow strong {
  font-weight: 700;
}

.addButton {
  display: inline-flex;
  min-width: 102px;
  min-height: 50px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  padding: 0 18px;
  border: 1.5px solid #ef1b23;
  border-radius: 12px;
  background: #ffffff;
  color: #ef1b23;
  cursor: pointer;
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
}

.addButton:hover,
.addButton:focus-visible {
  background: #fff4f5;
}

/* ======================================================
   POPUP
   Sized to match the Full Home / Villa modal footprint.
   ====================================================== */

.modalOverlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  box-sizing: border-box;
  padding: 16px;
  align-items: center;
  justify-content: center;
  background: rgba(14, 14, 14, 0.72);
}

.modal {
  display: flex;
  width: min(558px, calc(100vw - 32px));
  height: min(640px, calc(100dvh - 32px));
  min-height: 0;
  overflow: hidden;
  border: 1px solid #f1d7db;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
  flex-direction: column;
}

.modalHeader {
  display: flex;
  box-sizing: border-box;
  min-height: 150px;
  flex: 0 0 auto;
  gap: 18px;
  padding: 34px 32px 27px;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid #eeeeee;
  background: #ffffff;
}

.modalHeader h2 {
  margin: 0;
  color: #161616;
  font-size: 28px;
  font-weight: 750;
  line-height: 1.16;
  letter-spacing: -0.025em;
}

.modalHeader p {
  max-width: 410px;
  margin: 10px 0 0;
  color: #626262;
  font-size: 14px;
  line-height: 1.5;
}

.closeButton {
  display: inline-flex;
  width: 48px;
  height: 48px;
  min-width: 48px;
  flex: 0 0 48px;
  align-items: center;
  justify-content: center;
  margin: -18px -18px 0 0;
  border: 1px solid #eeeeee;
  border-radius: 50%;
  background: #ffffff;
  color: #171717;
  cursor: pointer;
  font-size: 29px;
  font-weight: 400;
  line-height: 1;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.05);
}

.modalBody {
  min-height: 0;
  flex: 1 1 auto;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 28px 32px 34px;
  overscroll-behavior: contain;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
}

.modalBody::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ======================================================
   POPUP PRICING
   ====================================================== */

.modalSection {
  width: 100%;
}

.modalSection + .modalSection,
.ratingSection {
  margin-top: 30px;
  padding-top: 28px;
  border-top: 1px solid #e9eaec;
}

.modalSection h3 {
  margin: 0 0 19px;
  color: #5c6678;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
}

.pricingGrid {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.priceCard {
  display: flex;
  box-sizing: border-box;
  min-height: 168px;
  padding: 16px 13px;
  border: 1px solid #dfe2e7;
  border-radius: 10px;
  background: #ffffff;
  flex-direction: column;
  align-items: flex-start;
}

.optionLabel {
  color: #303746;
  font-size: 15px;
  font-weight: 400;
  line-height: 1.42;
}

.priceCard strong {
  margin-top: 20px;
  color: #525d6f;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.25;
}

.priceCard button {
  display: inline-flex;
  min-width: 85px;
  min-height: 42px;
  margin-top: auto;
  padding: 0 18px;
  align-items: center;
  justify-content: center;
  border: 1.5px solid #ef1b23;
  border-radius: 9px;
  background: #ffffff;
  color: #ef1b23;
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
}

.priceCard button:hover,
.priceCard button:focus-visible {
  background: #ef1b23;
  color: #ffffff;
}

/* ======================================================
   PROCESS / INCLUDED
   ====================================================== */

.processList {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
  flex-direction: column;
  gap: 18px;
}

.processList li {
  display: grid;
  grid-template-columns: 29px minmax(0, 1fr);
  gap: 3px;
}

.processNumber {
  color: #7b8495;
  font-size: 15px;
  line-height: 1.45;
}

.processList strong {
  color: #606a7c;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.4;
}

.processList p {
  margin: 4px 0 0;
  color: #7b8598;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.55;
}

.simpleList {
  display: flex;
  margin: 0;
  padding: 0 0 0 21px;
  color: #697387;
  flex-direction: column;
  gap: 14px;
}

.simpleList li {
  padding-left: 5px;
  font-size: 15px;
  line-height: 1.45;
}

/* ======================================================
   RATING
   ====================================================== */

.ratingSection {
  padding-bottom: 8px;
}

.ratingSummary {
  display: flex;
  align-items: center;
  gap: 10px;
}

.goldStar {
  color: #f6b900;
  font-size: 28px;
  line-height: 1;
}

.ratingSummary strong {
  color: #586171;
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
}

.ratingReviewCount {
  margin: 10px 0 24px;
  color: #7e8797;
  font-size: 14px;
  line-height: 1.4;
}

.ratingBars {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 15px;
}

.ratingBarRow {
  display: grid;
  width: 100%;
  grid-template-columns: 34px minmax(0, 1fr) 43px;
  gap: 10px;
  align-items: center;
}

.ratingLabel {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: #596273;
  font-size: 14px;
  line-height: 1;
}

.ratingLabel span {
  color: #f6b900;
}

.ratingTrack {
  display: block;
  width: 100%;
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: #d4d4d4;
}

.ratingFill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #ef1b23;
}

.ratingPercent {
  color: #7c8595;
  font-size: 13px;
  text-align: right;
}

/* ======================================================
   TABLET
   ====================================================== */

