.section { box-sizing: border-box; width: 100%; background: #fff; color: #171717; }
.container { box-sizing: border-box; width: min(928px, calc(100% - 32px)); margin: 0 auto; padding: 28px 0 64px; }
.columns { display: grid; grid-template-columns: minmax(0, 590px) minmax(0, 310px); gap: 28px; align-items: start; }
.main { min-width: 0; border-right: 1px solid #f4d9de; padding-bottom: 60px; }
.sidebar { min-width: 0; position: sticky; top: 170px; }
.eyebrow { margin: 0 0 18px; color: #ef1b23; font-size: 18px; font-weight: 700; line-height: 1.3; }
.selectorViewport { position: relative; width: 100%; min-width: 0; }
.selector { display: flex; flex-wrap: nowrap; gap: 4px; width: 100%; overflow-x: auto; overflow-y: hidden; margin: 0 0 10px; padding: 0 0 6px; scroll-snap-type: x mandatory; scroll-behavior: smooth; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.selector::-webkit-scrollbar { display: none; }
.selectorItem { display: flex; flex: 0 0 100px; width: 100px; min-width: 100px; align-items: center; flex-direction: column; gap: 8px; padding: 0; border: 0; background: transparent; font: inherit; cursor: pointer; scroll-snap-align: start; }
.thumbnail { display: block; width: 100px; height: 100px; flex: 0 0 100px; background: #fff4f5; }
.selectorLabel { display: block; width: 100px; font-size: 13px; line-height: 1.16; text-align: center; }
.selectorItem:hover .selectorLabel, .selectorItem:focus-visible .selectorLabel { color: #ef1b23; }
.selectorPrevious, .selectorNext { position: absolute; z-index: 2; top: 47px; display: flex; width: 38px; height: 38px; align-items: center; justify-content: center; padding: 0; border: 1px solid #f3cbd0; border-radius: 50%; background: #fff; color: #ef1b23; box-shadow: 0 2px 10px #00000015; font-size: 24px; cursor: pointer; }
.selectorPrevious { left: 1px; }
.selectorNext { right: 1px; }
.selectorPrevious:hover, .selectorNext:hover { background: #ef1b23; color: #fff; }
.serviceGroup { width: 100%; scroll-margin-top: 145px; padding: 10px 0 25px; border-bottom: 1px solid #f0dfe2; }
.serviceGroup + .serviceGroup { padding-top: 25px; }
.serviceGroup h2 { margin: 0 0 12px; font-size: 28px; font-weight: 700; line-height: 1.2; }
.banner { width: 100%; aspect-ratio: 1940 / 811; background: #fff4f5 center / contain no-repeat; }
.serviceRow { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 0 0; }
.serviceRow h3 { margin: 0 0 6px; font-size: 19px; line-height: 1.25; }
.serviceRow strong { display: inline-block; margin-top: 11px; }
.rating { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; color: #555f6c; }
.star { color: #ef1b23; }
.rating button { padding: 0 0 0 7px; border: 0; background: transparent; color: #e71922; font: inherit; font-weight: 600; cursor: pointer; }
.addButton { min-width: 85px; min-height: 42px; padding: 8px 16px; border: 1px solid #ef1b23; border-radius: 10px; background: #fff; color: #ef1b23; font-size: 16px; font-weight: 700; cursor: pointer; }
.addButton:hover { background: #ef1b23; color: #fff; }
.backdrop { position: fixed; inset: 0; z-index: 10000; display: flex; align-items: center; justify-content: center; padding: 16px; background: #0009; }
.modal { display: flex; width: min(472px, calc(100vw - 32px)); max-height: calc(100dvh - 32px); flex-direction: column; overflow: hidden; border-radius: 18px; background: #fff; box-shadow: 0 20px 70px #0004; }
.modalHeader { display: flex; justify-content: space-between; gap: 12px; padding: 18px 22px; border-bottom: 1px solid #e6e8ef; }
.modalHeader h2 { margin: 0 0 6px; font-size: 25px; line-height: 1.2; }
