.modalHeader p { margin: 0; color: #ef1b23; font-weight: 700; }
.closeButton { align-self: start; border: 0; background: transparent; font-size: 29px; cursor: pointer; }
.modalBody { min-height: 0; overflow-y: auto; padding: 18px 22px; color: #4e5968; font-size: 14px; line-height: 1.5; }
