export default function WhyChooseUsSection() {
  const sectionRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const section = sectionRef.current;

    if (!section) {
      return;
    }

    const animatedElements =
      section.querySelectorAll<HTMLElement>("[data-reveal]");

    let hasRevealed = false;
    let previousScrollY = window.scrollY;

    const showImmediately = () => {
      section.classList.add("reveal-instant");

      animatedElements.forEach((element) => {
        element.classList.add("is-visible");
      });
    };

    if (typeof IntersectionObserver === "undefined") {
      showImmediately();
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        const currentScrollY = window.scrollY;
        const scrollingDown = currentScrollY >= previousScrollY;
        const enteringFromTop = entry.boundingClientRect.top >= 0;

        previousScrollY = currentScrollY;

        if (!entry.isIntersecting || hasRevealed) {
          return;
        }

        hasRevealed = true;

        if (!scrollingDown || !enteringFromTop) {
          section.classList.add("reveal-instant");
        }

        animatedElements.forEach((element) => {
          element.classList.add("is-visible");
        });

        observer.disconnect();
      },
      {
        root: null,
        threshold: 0.08,
        rootMargin: "48px 0px -7% 0px",
      },
    );

    observer.observe(section);

    return () => {
      observer.disconnect();
    };
  }, []);

  return (
    <section
      ref={sectionRef}
      className="why-choose-section relative isolate overflow-hidden bg-white pb-24 pt-12 sm:pb-28 sm:pt-14 lg:pb-32 lg:pt-16"
