  input: unknown,
): OfficeCleaningPlan | null {
  if (!Array.isArray(input) || input.length !== 1) {
    return null;
  }

  const raw = input[0] as
    | {
        id?: unknown;
        quantity?: unknown;
      }
    | undefined;

  if (
    !raw ||
    typeof raw.id !== "string" ||
    typeof raw.quantity !== "number"
  ) {
    return null;
  }

  const service = OFFICE_CLEANING_SERVICES.find(
    (item) => item.id === raw.id,
  );

  if (!service) {
    return null;
  }

  const lineTotal = calculateOfficeCleaningEstimate(
    service,
    raw.quantity,
  );

  if (lineTotal === null) {
    return null;
  }

  return {
    services: [
      {
        id: service.id,
        name: service.name,
        quantity: raw.quantity,
        unitPrice: service.rate,
        lineTotal,
      },
    ],
    total: lineTotal,
    advanceAmount: Math.round(lineTotal * 0.5),
  };
}

